/* ============================================================
   TURQUESA HUB · ESPACIO DE ORGANIZACIONES
   Inicio, perfil, autodiagnóstico, resultados y brechas, plan de acción
   (selección de recomendaciones, acciones propias, responsables, fechas,
   metas, indicadores, evidencias, estados), seguimiento de compromisos,
   colaboradores (invitaciones, asignación, cobertura agregada),
   sensibilización, biblioteca, reportes, Sello (información e interés),
   cuenta y datos.
   ============================================================ */
window.TH = window.TH || {};

(function () {
  const esc = (s) => TH.util.esc(s);
  const ic = (n, c) => TH.ui.icono(n, c);
  const cat = TH.data.catalogos; const instr = TH.data.instrumento;
  const preguntas = () => TH.api.diagnostico.preguntas();
  const ROLES = ['organizacion'];
  const ui = { planVista: 'tabla', planFiltroEstado: '', planFiltroDim: '', planFiltroResp: '', bibliotecaQ: '', bibliotecaCat: '', bibliotecaTema: '', colabTab: 'colaboradores', seleccionSug: null };
  const org = () => TH.auth.organizacion(); const orgId = () => TH.auth.orgId();
  const dimNombre = (id) => (instr.dimensiones.find(d => d.id === id) || {}).corto || id;

  /* ================= INICIO ================= */
  function inicio() {
    const o = org(); const r = TH.api.organizaciones.resumen(o.id); const ob = o.onboarding || {};
    if (!ob.bienvenida) return bienvenida(o);
    const res = r.diag && r.diag.estado === 'completado' ? TH.api.diagnostico.calcular(r.diag) : null;
    const form = TH.api.formacion.agregadosOrganizacion(o.id);
    const pr = TH.api.plan.resumen(r.plan);
    const pasos = [
      { k: 'perfil', t: 'Perfil organizacional', d: 'Confirma los datos de tu organización.', min: 5, ruta: '/organizacion/perfil', hecho: !!ob.perfil },
      { k: 'diagnostico', t: 'Autodiagnóstico', d: preguntas().length + ' preguntas en seis dimensiones.', min: 20, ruta: '/organizacion/diagnostico', hecho: r.diagnosticoEstado === 'completado' },
      { k: 'plan', t: 'Plan de acción', d: 'Selecciona recomendaciones y define compromisos.', min: 25, ruta: '/organizacion/plan-accion', hecho: !!r.plan },
      { k: 'colaboradores', t: 'Colaboradores', d: 'Invita a tu equipo y asigna módulos.', min: 10, ruta: '/organizacion/colaboradores', hecho: r.colaboradoresInvitados > 0 },
      { k: 'seguimiento', t: 'Seguimiento', d: 'Actualiza avances y registra evidencias.', min: 10, ruta: '/organizacion/plan-accion/seguimiento', hecho: pr.completadas > 0 }
    ];
    const siguiente = pasos.find(p => !p.hecho); const hechos = pasos.filter(p => p.hecho).length;
    return TH.ui.encabezado('Hola, ' + esc(o.responsable.split(' ')[0]), 'Estado de la gestión preventiva de <strong>' + esc(o.nombre) + '</strong>.') +
      (siguiente ? TH.ui.siguientePaso('Siguiente paso: ' + siguiente.t, siguiente.d + ' Tiempo estimado: ' + siguiente.min + ' min.', siguiente.ruta, 'Ir ahora') : TH.ui.siguientePaso('Tu gestión preventiva está en marcha', 'Mantén el plan al día, registra evidencias y revisa los resultados periódicamente.', '/organizacion/plan-accion/seguimiento', 'Ver seguimiento')) +
      '<div class="grid grid-4 mt-5">' +
      TH.ui.kpi('Autodiagnóstico', r.diagnosticoEstado === 'completado' ? res.global + '%' : r.diagnosticoPct + '%', r.diagnosticoEstado === 'completado' ? 'Lectura orientativa · ' + res.nivelGlobal.nombre : 'Preguntas completadas', true) +
      TH.ui.kpi('Plan de acción', r.accionesTotal ? r.planPct + '%' : '—', r.accionesTotal ? r.accionesCompletadas + ' de ' + r.accionesTotal + ' acciones completadas' : 'Sin plan') +
      TH.ui.kpi('Acciones vencidas', String(r.accionesVencidas), r.accionesVencidas ? 'Requieren atención' : 'Al día') +
      TH.ui.kpi('Sensibilización', form.coberturaPct + '%', form.colaboradoresConAlMenosUno + ' de ' + form.colaboradores + ' colaboradores con un módulo completo') + '</div>' +
      '<div class="grid grid-sidebar mt-5"><div><div class="card"><div class="card__encabezado"><div><h3 class="card__titulo">Tu recorrido</h3><p class="card__sub">' + hechos + ' de ' + pasos.length + ' etapas</p></div></div>' + TH.ui.progreso(TH.util.pct(hechos, pasos.length), { color: 'exito' }) +
      '<ol class="stepper stepper--vertical mt-4">' + pasos.map(p => '<li class="' + (p.hecho ? 'es-completo' : (siguiente && siguiente.k === p.k ? 'es-actual' : '')) + '"><div class="grow"><strong>' + esc(p.t) + '</strong><div class="texto-2 texto-sm">' + esc(p.d) + ' · ' + p.min + ' min</div></div><a class="btn btn--terciario btn--sm" href="#' + p.ruta + '">' + (p.hecho ? 'Revisar' : 'Ir') + '</a></li>').join('') + '</ol></div>' +
      (res ? '<div class="card mt-4"><h3 class="card__titulo">Lectura por dimensión</h3><p class="card__sub mb-4">Orientativa y basada en lo declarado por tu organización.</p>' + TH.graficos.barras(res.dimensiones.map(d => ({ etiqueta: d.dim.corto, valor: d.puntaje }))) + '</div>' : '') +
      (pr.proximas.length || pr.vencidas.length ? '<div class="card mt-4"><h3 class="card__titulo">Compromisos próximos y vencidos</h3>' + TH.ui.tabla([{ titulo: 'Acción', render: a => '<a href="#/organizacion/plan-accion/detalle?id=' + a.id + '">' + esc(a.objetivo) + '</a>' }, { titulo: 'Responsable', campo: 'responsable' }, { titulo: 'Fecha', render: a => (a.fechaObjetivo < TH.util.hoy() ? '<span class="texto-riesgo">' : '<span>') + esc(TH.util.fecha(a.fechaObjetivo)) + '</span>' }, { titulo: 'Estado', render: a => TH.ui.badgeCatalogo(cat.estadosAccion, a.estado) }], pr.vencidas.concat(pr.proximas).slice(0, 6), { caption: 'Compromisos' }) + '</div>' : '') +
      '</div><div>' +
      '<div class="card"><h3 class="card__titulo">Evolución institucional</h3>' + TH.ui.dl([['Registro', TH.util.fecha(o.fechaRegistro)], ['Autodiagnóstico', r.diag ? (r.diag.estado === 'completado' ? 'Completado ' + TH.util.fecha(r.diag.fechaFin) + ' (ciclo ' + (r.diag.ciclo || 1) + ')' : 'En curso') : 'No iniciado'], ['Plan creado', r.plan ? TH.util.fecha(r.plan.fechaCreacion) : '—'], ['Evidencias registradas', String(r.evidenciasTotal)], ['Colaboradores', String(r.colaboradoresActivos)], ['Sello Turquesa', r.interesSello ? 'Interés manifestado' : 'Sin manifestación de interés']]) + '</div>' +
      '<div class="card card--suave mt-4"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Recordatorio</h3><p class="texto-sm mb-0">Turquesa Hub no recibe denuncias ni gestiona casos. Las obligaciones de atención corresponden a tu organización dentro de su competencia y a las autoridades. Consulta <a href="#/organizacion/biblioteca?id=rec-respuesta">Prevención y respuesta institucional</a> y <a href="#/organizacion/biblioteca?id=rec-rutas">Orientación segura y rutas competentes</a>.</p></div></div></div>';
  }
  function bienvenida(o) {
    return '<div style="max-width:820px;margin:auto"><div class="card card--borde-sup"><div class="seccion__eyebrow">Bienvenida</div><h1>Bienvenida a Turquesa Hub, ' + esc(o.nombre) + '</h1>' +
      '<p class="texto-2">Tu espacio está listo. En pocos pasos tendrás un autodiagnóstico, tus brechas, un plan de acción con responsables y seguimiento, y la ruta para formar a tu equipo.</p>' +
      '<h3 class="mt-5">¿Qué es Turquesa Hub?</h3><p>Una plataforma para convertir compromisos en acciones de prevención de violencias basadas en género. No es un sistema de denuncias ni de gestión de casos: es tu herramienta de gestión preventiva. El autodiagnóstico es orientativo y se basa en lo que tu organización declara.</p>' +
      '<h3 class="mt-5">Pasos recomendados</h3>' + TH.ui.stepper([{ texto: 'Confirmar el perfil organizacional', desc: '5 minutos.' }, { texto: 'Autodiagnóstico', desc: '20 minutos · puedes guardar y continuar después.' }, { texto: 'Plan de acción', desc: '25 minutos · selecciona recomendaciones y define responsables y fechas.' }, { texto: 'Invitar colaboradores', desc: '10 minutos · asigna módulos de sensibilización.' }, { texto: 'Seguimiento', desc: 'Actualiza avances y registra evidencias.' }], 0, true) +
      '<div class="flex gap-3 wrap mt-5"><button type="button" class="btn btn--primario btn--lg" data-action="org-iniciar-onboarding" data-ruta="/organizacion/diagnostico">Comenzar con el autodiagnóstico ' + ic('flecha') + '</button><button type="button" class="btn btn--secundario btn--lg" data-action="org-iniciar-onboarding" data-ruta="/organizacion/inicio">Ir a mi panel</button></div></div></div>';
  }

  /* ================= PERFIL ================= */
  function perfil() {
    const o = org();
    return TH.ui.encabezado('Perfil organizacional', 'Datos de caracterización. Se usan en los reportes y para contextualizar las recomendaciones.') +
      '<form class="card" data-form="org-perfil" novalidate><div class="form-fila">' +
      TH.ui.campo({ name: 'nombre', label: 'Razón social o denominación', required: true, valor: o.nombre }) +
      TH.ui.campo({ name: 'identificacion', label: 'Identificación (' + esc(TH.util.nombreCatalogo(cat.tiposIdentificacion, o.tipoIdentificacion)) + ')', valor: o.identificacion, disabled: true, ayuda: 'Para cambiar la identificación, contacta a la Fundación Milagro de Abril.' }) +
      TH.ui.campo({ name: 'sector', label: 'Sector', tipo: 'select', required: true, opciones: cat.sectores, valor: o.sector }) +
      TH.ui.campo({ name: 'tamano', label: 'Tamaño', tipo: 'select', required: true, opciones: cat.tamanos, valor: o.tamano }) +
      TH.ui.campo({ name: 'departamento', label: 'Departamento', valor: o.departamento, required: true }) +
      TH.ui.campo({ name: 'municipio', label: 'Municipio', valor: o.municipio, required: true }) +
      TH.ui.campo({ name: 'emailInstitucional', label: 'Correo institucional', tipo: 'email', required: true, valor: o.emailInstitucional || '' }) +
      TH.ui.campo({ name: 'telefono', label: 'Teléfono institucional', tipo: 'tel', valor: o.telefono || '' }) +
      TH.ui.campo({ name: 'responsable', label: 'Persona responsable', required: true, valor: o.responsable }) +
      TH.ui.campo({ name: 'cargo', label: 'Cargo', tipo: 'select', opciones: cat.cargos, valor: o.cargo }) +
      TH.ui.campo({ name: 'acompanamiento', label: 'Necesidades de acompañamiento (visible para la Fundación)', tipo: 'textarea', valor: o.acompanamiento, ayuda: 'Describe en qué te gustaría recibir apoyo del equipo Turquesa.' }) +
      '</div><div class="flex justify-end gap-2"><button type="submit" class="btn btn--primario">Guardar cambios</button></div></form>';
  }

  /* ================= AUTODIAGNÓSTICO ================= */
  function diagnostico(ctx) {
    const d = TH.api.diagnostico.obtener(orgId());
    if (!d) return diagnosticoIntro();
    if (d.estado === 'completado' && !ctx.params.revisar) return diagnosticoCompletado(d);
    const lista = preguntas(); const idx = TH.util.clamp(d.preguntaActual || 0, 0, lista.length - 1);
    const p = lista[idx]; const dim = instr.dimensiones.find(x => x.id === p.dim); const resp = d.respuestas[p.id];
    const pend = TH.api.diagnostico.pendientes(d); const respondidas = lista.filter(q => d.respuestas[q.id]).length;
    const nav = lista.map((q, i) => '<button type="button" data-action="diag-ir" data-indice="' + i + '" class="' + (i === idx ? 'es-actual' : d.respuestas[q.id] ? 'es-respondida' : '') + '" aria-label="Pregunta ' + (i + 1) + (d.respuestas[q.id] ? ', respondida' : ', pendiente') + '" ' + (i === idx ? 'aria-current="true"' : '') + '>' + (i + 1) + '</button>').join('');
    return TH.ui.migas([{ texto: 'Inicio', ruta: '/organizacion/inicio' }, { texto: 'Autodiagnóstico' }]) +
      TH.ui.encabezado('Autodiagnóstico institucional guiado', 'Seis dimensiones · ' + lista.length + ' preguntas · se guarda automáticamente.', TH.ui.guardadoAuto(d.ultimoGuardado)) +
      '<div class="grid grid-sidebar"><div>' +
      '<div class="mb-4">' + TH.ui.progreso(TH.util.pct(respondidas, lista.length), { etiqueta: respondidas + ' de ' + lista.length + ' respondidas', aria: 'Progreso del autodiagnóstico' }) + '</div>' +
      '<article class="pregunta" aria-labelledby="pregunta-texto"><div class="pregunta__dim">Dimensión ' + dim.orden + ' · ' + esc(dim.nombre) + '</div>' +
      '<h2 class="pregunta__texto" id="pregunta-texto">' + (idx + 1) + '. ' + esc(p.texto) + '</h2><p class="pregunta__contexto">' + esc(p.contexto) + '</p>' +
      '<form data-form="diag-responder" data-pregunta="' + p.id + '" novalidate><fieldset><legend class="sr-only">Opciones de respuesta</legend><div class="opciones">' +
      instr.opciones.filter(o => o.id !== 'na' || p.permiteNA).map(o => '<label class="opcion"><input type="radio" name="opcion" value="' + o.id + '" ' + (resp && resp.opcion === o.id ? 'checked' : '') + ' data-change="diag-opcion" required><span><strong>' + esc(o.nombre) + '</strong><br><span class="texto-2 texto-xs">' + esc(o.desc) + '</span></span></label>').join('') + '</div></fieldset>' +
      (p.permiteNA ? '<div class="campo mt-3 ' + (resp && resp.opcion === 'na' ? '' : 'hidden') + '" id="diag-justificacion"><label class="campo__label" for="just">Justificación de "No aplica"<span class="req" aria-hidden="true">*</span></label><textarea class="textarea" id="just" name="justificacion" rows="2">' + esc(resp && resp.justificacion ? resp.justificacion : '') + '</textarea><span class="campo__error" role="alert"></span></div>' : '') +
      '<details class="ayuda"><summary>Ayuda contextual</summary><div class="ayuda__cuerpo">' + esc(p.ayuda) + '</div></details>' +
      '<details class="ayuda"><summary>Capacidad que examina, fundamento y evidencia esperada</summary><div class="ayuda__cuerpo">' + TH.ui.dl([['Capacidad', p.capacidad], ['Justificación', p.justificacion], ['Evidencia esperada', p.evidenciaEjemplo], ['Interpretación', p.reglaInterpretacion]]) + '<div class="mt-3"><strong class="texto-sm">Fuentes</strong>' + TH.ui.referencias(p.fuentes) + '</div></div></details>' +
      '<div class="flex justify-between gap-3 mt-5 wrap"><button type="button" class="btn btn--secundario" data-action="diag-ir" data-indice="' + (idx - 1) + '" ' + (idx === 0 ? 'disabled' : '') + '>' + ic('flechaIzq') + ' Anterior</button>' +
      '<div class="flex gap-2"><button type="button" class="btn btn--terciario" data-action="diag-guardar-salir">Guardar y continuar después</button>' +
      (idx < lista.length - 1 ? '<button type="submit" class="btn btn--primario">Guardar y siguiente ' + ic('flecha') + '</button>' : '<button type="submit" class="btn btn--primario">Guardar respuesta</button>') + '</div></div></form></article>' +
      (pend.length === 0 ? '<div class="mt-4">' + (d.estado === 'completado' ? TH.ui.alerta('info', 'Autodiagnóstico completado', 'Puedes ajustar respuestas; los resultados se recalculan. <a href="#/organizacion/diagnostico/resultados">Ver resultados</a>.') : TH.ui.alerta('exito', 'Todas las preguntas tienen respuesta', 'Finaliza para ver tus resultados y brechas.') + '<button type="button" class="btn btn--primario btn--lg" data-action="diag-finalizar">Finalizar y ver resultados</button>') + '</div>' :
        (idx === lista.length - 1 ? '<div class="mt-4">' + TH.ui.alerta('alerta', 'Preguntas pendientes', 'Faltan ' + pend.length + ': ' + pend.map(q => '<button type="button" class="btn btn--terciario btn--sm" data-action="diag-ir" data-indice="' + lista.indexOf(q) + '">#' + (lista.indexOf(q) + 1) + '</button>').join(' ')) + '</div>' : '')) +
      '</div><aside><div class="card card--compacta"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Navegación</h3><p class="card__sub mb-3">Verde: respondida · Turquesa: actual</p><div class="nav-preguntas">' + nav + '</div>' +
      '<hr><h4 class="texto-sm">Dimensiones</h4>' + instr.dimensiones.map(dm => { const qs = lista.filter(q => q.dim === dm.id); const n = qs.filter(q => d.respuestas[q.id]).length; return '<div class="texto-sm flex justify-between gap-2" style="padding:4px 0"><span class="' + (dm.id === dim.id ? '' : 'texto-2') + '">' + esc(dm.corto) + '</span><span>' + n + '/' + qs.length + '</span></div>'; }).join('') +
      '</div><div class="card card--suave card--compacta mt-4"><p class="texto-sm mb-0"><strong>Instrumento v' + esc(instr.version) + '.</strong> ' + esc(instr.nota) + '</p></div></aside></div>';
  }
  function diagnosticoIntro() {
    const lista = preguntas();
    return TH.ui.encabezado('Autodiagnóstico institucional guiado', 'Reconoce las capacidades de tu organización para prevenir las violencias basadas en género, con base en lo que tu organización declara.') +
      '<div class="grid grid-sidebar"><div class="card"><h3>Antes de empezar</h3><ul><li>Son <strong>' + lista.length + ' preguntas</strong> en seis dimensiones. Tiempo estimado: 20 minutos.</li><li>Puedes responder en varias sesiones: el progreso se guarda automáticamente.</li><li>Cada pregunta trae contexto, ayuda, la capacidad que examina, su fundamento y la evidencia esperada. Si no tienes información, elige "No sé": generará una acción de verificación.</li><li>Los resultados generan una lectura orientativa por dimensión, brechas identificadas y recomendaciones para tu plan de acción.</li></ul>' +
      '<h4 class="mt-4">Dimensiones</h4><ol>' + instr.dimensiones.map(d => '<li><strong>' + esc(d.nombre) + '.</strong> <span class="texto-2">' + esc(d.desc) + '</span></li>').join('') + '</ol>' +
      '<button type="button" class="btn btn--primario btn--lg mt-4" data-action="diag-iniciar">Iniciar el autodiagnóstico ' + ic('flecha') + '</button></div>' +
      '<aside>' + TH.ui.alerta('info', 'Qué es y qué no es', 'Es un autodiagnóstico declarado por la propia organización. No es una evaluación psicométrica validada, no es una auditoría legal, no certifica cumplimiento normativo y no evalúa casos individuales. Distingue lo declarado de lo que tiene evidencia registrada.') + '<div class="card card--compacta"><p class="texto-sm"><strong>Instrumento v' + esc(instr.version) + '.</strong> ' + esc(instr.nota) + '</p><strong class="texto-sm">Fundamentos</strong>' + TH.ui.referencias(instr.referencias.slice(0, 6)) + '</div></aside></div>';
  }
  function diagnosticoCompletado(d) {
    const res = TH.api.diagnostico.calcular(d);
    return TH.ui.encabezado('Autodiagnóstico completado', 'Completado el ' + TH.util.fechaLarga(d.fechaFin) + ' con el instrumento v' + esc(d.instrumentoVersion) + ' (ciclo ' + (d.ciclo || 1) + ').', '<a class="btn btn--primario" href="#/organizacion/diagnostico/resultados">Ver resultados y brechas</a><a class="btn btn--secundario" href="#/organizacion/diagnostico?revisar=1">Revisar respuestas</a>') +
      '<div class="grid grid-2"><div class="card flex items-center gap-5">' + TH.graficos.donut(res.global, { etiqueta: 'Lectura orientativa' }) + '<div><h3>' + esc(res.nivelGlobal.nombre) + '</h3><p class="texto-2 texto-sm">' + esc(res.nivelGlobal.desc) + '</p>' + TH.ui.badge(res.fortalezas.length + ' fortalezas declaradas', 'exito') + ' ' + TH.ui.badge(res.brechas.length + ' brechas', 'alerta') + '</div></div>' +
      '<div class="card"><h3 class="card__titulo">Nuevo ciclo</h3><p class="card__sub">Cuando hayas avanzado en el plan de acción, responde de nuevo el autodiagnóstico para comparar. El actual quedará archivado como línea base.</p><button type="button" class="btn btn--secundario mt-3" data-action="diag-nuevo-ciclo">Iniciar nuevo ciclo</button></div></div>';
  }
  function resultados() {
    const d = TH.api.diagnostico.obtener(orgId());
    if (!d || d.estado !== 'completado') return TH.ui.vacio('Aún no hay resultados', 'Completa el autodiagnóstico para ver tus resultados, brechas y recomendaciones.', '<a class="btn btn--primario" href="#/organizacion/diagnostico">Ir al autodiagnóstico</a>', 'diagnostico');
    const res = TH.api.diagnostico.calcular(d); const rec = TH.api.diagnostico.recomendaciones(res); const plan = TH.api.plan.obtener(orgId());
    const archivados = (TH.store.get().diagnosticosArchivados || []).filter(x => x.orgId === orgId() && x.resultadoSnapshot);
    return TH.ui.migas([{ texto: 'Inicio', ruta: '/organizacion/inicio' }, { texto: 'Autodiagnóstico', ruta: '/organizacion/diagnostico' }, { texto: 'Resultados y brechas' }]) +
      TH.ui.encabezado('Resultados y análisis de brechas', 'Lectura orientativa del autodiagnóstico completado el ' + TH.util.fechaLarga(d.fechaFin) + '.', (plan ? '<a class="btn btn--primario" href="#/organizacion/plan-accion">Ver plan de acción</a>' : '<a class="btn btn--primario" href="#/organizacion/plan-accion">Construir plan de acción ' + ic('flecha') + '</a>') + '<a class="btn btn--secundario" href="#/organizacion/reportes">Descargar reporte</a>') +
      TH.ui.alerta('info', 'Cómo leer estos resultados', 'El <strong>porcentaje de preguntas completadas</strong> (' + res.completadoPct + '%) indica cuánto del instrumento se respondió. El <strong>valor orientativo</strong> (' + res.global + '%) resume lo que tu organización declaró: no es una evaluación validada de madurez, ni cumplimiento legal, ni certificación. Las fortalezas se marcan como <strong>declaradas</strong> y, cuando el plan de acción tiene evidencias vinculadas, como <strong>con evidencia registrada</strong>.') +
      '<div class="grid grid-2"><div class="card"><h3 class="card__titulo">Resumen</h3><div class="flex items-center gap-5 mt-3">' + TH.graficos.donut(res.global, { etiqueta: 'Lectura orientativa' }) + '<div><div class="mb-2">' + TH.ui.badgeNivel(res.nivelGlobal) + '</div><p class="texto-sm texto-2">' + esc(res.nivelGlobal.desc) + '</p><p class="texto-sm">' + res.fortalezas.length + ' fortalezas declaradas (' + res.conEvidencia + ' con evidencia) · ' + res.brechas.length + ' brechas · ' + res.sinInformacion.length + ' sin información</p></div></div></div>' +
      '<div class="card"><h3 class="card__titulo">Perfil por dimensión</h3>' + TH.graficos.radar(res.dimensiones.map(x => ({ etiqueta: x.dim.corto, valor: x.puntaje }))) + '</div></div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Lectura por dimensión</h3>' + res.dimensiones.map(x => '<div class="dimension-fila"><span class="dimension-fila__nombre">' + esc(x.dim.nombre) + '</span>' + TH.ui.progreso(x.puntaje || 0, { aria: x.dim.nombre, sinValor: true }) + '<strong>' + (x.puntaje === null ? 'N/A' : x.puntaje + '%') + '</strong>' + TH.ui.badgeNivel(x.nivel) + '</div>').join('') + '</div>' +
      (archivados.length ? '<div class="card mt-4"><h3 class="card__titulo">Comparación con ciclos anteriores</h3>' + TH.ui.tabla([{ titulo: 'Ciclo', render: x => 'Ciclo ' + (x.ciclo || 1) }, { titulo: 'Fecha', render: x => esc(TH.util.fecha(x.fechaFin)) }, { titulo: 'Valor global', clase: 'num', render: x => x.resultadoSnapshot.global + '%' }].concat(instr.dimensiones.map(dm => ({ titulo: dm.corto, clase: 'num', render: x => { const v = (x.resultadoSnapshot.dimensiones.find(z => z.dim === dm.id) || {}).puntaje; return v == null ? '—' : v + '%'; } }))), archivados.concat([Object.assign({}, d, { resultadoSnapshot: { global: res.global, dimensiones: res.dimensiones.map(z => ({ dim: z.dim.id, puntaje: z.puntaje })) } })]), { caption: 'Ciclos' }) + '</div>' : '') +
      '<div class="grid grid-2 mt-4"><div class="card"><h3 class="card__titulo">Fortalezas declaradas</h3>' + (res.fortalezas.length ? '<ul class="texto-sm">' + res.fortalezas.map(f => '<li>' + TH.ui.badge(f.dim.corto, 'turquesa') + ' ' + esc(f.pregunta.accion.objetivo) + ' ' + (f.evidencias ? TH.ui.badge('Con evidencia (' + f.evidencias + ')', 'exito') : TH.ui.badge('Declarada', 'neutro')) + '</li>').join('') + '</ul>' : '<p class="texto-2">Aún no se identifican elementos plenamente implementados.</p>') + '</div>' +
      '<div class="card"><h3 class="card__titulo">Brechas identificadas</h3>' + (res.brechas.length ? '<ul class="texto-sm">' + res.brechas.map(b => '<li>' + TH.ui.badge(b.opcion === 'parcial' ? 'Parcial' : 'No implementado', b.opcion === 'parcial' ? 'alerta' : 'error') + ' ' + esc(b.pregunta.accion.objetivo) + '</li>').join('') + '</ul>' : '<p class="texto-2">No se identificaron brechas.</p>') + (res.sinInformacion.length ? '<h4 class="mt-3">Sin información suficiente (requieren verificación)</h4><ul class="texto-sm">' + res.sinInformacion.map(b => '<li>' + esc(b.pregunta.accion.objetivo) + '</li>').join('') + '</ul>' : '') + '</div></div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Recomendaciones iniciales</h3><p class="card__sub mb-3">Prioridades sugeridas a partir de las dimensiones con menor valor. Cada recomendación del plan indica su fundamento.</p><ol>' + rec.map(r => '<li><strong>' + esc(r.dim.nombre) + ' (' + r.puntaje + '%).</strong> ' + esc(r.texto) + '</li>').join('') + '</ol></div>';
  }

  /* ================= PLAN DE ACCIÓN ================= */
  function planAccion() {
    const plan = TH.api.plan.obtener(orgId()); const d = TH.api.diagnostico.obtener(orgId());
    if (!plan) {
      if (!d || d.estado !== 'completado') return TH.ui.encabezado('Plan de acción organizacional', 'Convierte las brechas en compromisos con responsables, fechas, metas, indicadores y evidencias.') + TH.ui.vacio('El plan se construye a partir del autodiagnóstico', 'Completa el autodiagnóstico para recibir recomendaciones, o añade acciones propias.', '<a class="btn btn--primario" href="#/organizacion/diagnostico">Ir al autodiagnóstico</a> <button type="button" class="btn btn--secundario" data-action="plan-nueva-accion">Añadir una acción propia</button>', 'plan');
      return seleccionRecomendaciones(d, null);
    }
    if (TH.router.parsear().params.incorporar) return seleccionRecomendaciones(d, plan);
    TH.api.plan.actualizarVencidas(orgId());
    const r = TH.api.plan.resumen(plan);
    const acciones = plan.acciones.filter(a => (!ui.planFiltroEstado || a.estado === ui.planFiltroEstado) && (!ui.planFiltroDim || a.dim === ui.planFiltroDim) && (!ui.planFiltroResp || TH.util.buscar(a.responsable, ui.planFiltroResp)));
    const noIncorporadas = d && d.estado === 'completado' ? TH.api.plan.generarSugeridas(d).filter(s => !plan.acciones.some(a => a.preguntaId === s.preguntaId)).length : 0;
    return TH.ui.migas([{ texto: 'Inicio', ruta: '/organizacion/inicio' }, { texto: 'Plan de acción' }]) +
      TH.ui.encabezado('Plan de acción organizacional', 'Creado el ' + TH.util.fecha(plan.fechaCreacion) + '. ' + r.total + ' acciones con enfoque SMART y mejora continua.', '<button type="button" class="btn btn--primario" data-action="plan-nueva-accion">' + ic('mas') + ' Añadir acción</button>' + (noIncorporadas ? '<a class="btn btn--secundario" href="#/organizacion/plan-accion?incorporar=1">Incorporar recomendaciones (' + noIncorporadas + ')</a>' : '') + '<button type="button" class="btn btn--secundario" data-action="plan-descargar-csv">' + ic('descargar') + ' CSV</button><a class="btn btn--secundario" href="#/organizacion/reportes">' + ic('imprimir') + ' Reporte</a>') +
      '<div class="grid grid-4 mb-4">' + TH.ui.kpi('Avance global', r.avance + '%', r.total + ' acciones', true) + TH.ui.kpi('Completadas', String(r.completadas), TH.util.pct(r.completadas, r.total) + '% del plan') + TH.ui.kpi('Vencidas', String(r.vencidas.length), r.vencidas.length ? 'Requieren reprogramación o cierre' : 'Al día') + TH.ui.kpi('Con evidencia', r.conEvidencia + '/' + r.total, r.evidencias + ' evidencias registradas') + '</div>' +
      (r.vencidas.length ? TH.ui.alerta('alerta', 'Acciones vencidas', r.vencidas.length + ' acción(es) superaron su fecha objetivo sin cerrarse: ' + r.vencidas.slice(0, 4).map(a => '<a href="#/organizacion/plan-accion/detalle?id=' + a.id + '">' + esc(a.objetivo.slice(0, 60)) + '</a>').join(' · ') + (r.vencidas.length > 4 ? ' …' : '')) : '') +
      '<div class="flex justify-between items-center wrap gap-3 mb-3"><div class="tabs mb-0" role="tablist" style="border:0"><button type="button" role="tab" aria-selected="' + (ui.planVista === 'tabla') + '" data-action="plan-vista" data-vista="tabla">' + ic('tabla') + ' Tabla</button><button type="button" role="tab" aria-selected="' + (ui.planVista === 'tablero') + '" data-action="plan-vista" data-vista="tablero">' + ic('tablero') + ' Tablero</button></div>' +
      '<div class="filtros mb-0"><div class="campo"><label class="sr-only" for="f-estado">Estado</label><select class="select" id="f-estado" data-change="plan-filtro-estado"><option value="">Todos los estados</option>' + cat.estadosAccion.map(e => '<option value="' + e.id + '" ' + (ui.planFiltroEstado === e.id ? 'selected' : '') + '>' + esc(e.nombre) + '</option>').join('') + '</select></div>' +
      '<div class="campo"><label class="sr-only" for="f-dim">Dimensión</label><select class="select" id="f-dim" data-change="plan-filtro-dim"><option value="">Todas las dimensiones</option>' + instr.dimensiones.map(x => '<option value="' + x.id + '" ' + (ui.planFiltroDim === x.id ? 'selected' : '') + '>' + esc(x.corto) + '</option>').join('') + '</select></div>' +
      '<div class="campo"><label class="sr-only" for="f-resp">Responsable</label><input class="input" id="f-resp" placeholder="Responsable" value="' + esc(ui.planFiltroResp) + '" data-input="plan-filtro-resp"></div></div></div>' +
      (ui.planVista === 'tabla' ? planTabla(acciones) : planTablero(acciones)) +
      '<div class="card mt-5"><h3 class="card__titulo">Avance por dimensión</h3>' + TH.graficos.barras(r.porDim.filter(x => x.total).map(x => ({ etiqueta: x.dim.corto + ' (' + x.completadas + '/' + x.total + ')', valor: x.avance }))) + '</div>';
  }
  function seleccionRecomendaciones(d, plan) {
    const sug = TH.api.plan.generarSugeridas(d).filter(s => !plan || !plan.acciones.some(a => a.preguntaId === s.preguntaId));
    if (ui.seleccionSug === null) ui.seleccionSug = sug.map(s => s.id);
    return TH.ui.migas([{ texto: 'Inicio', ruta: '/organizacion/inicio' }, { texto: 'Plan de acción' }]) +
      TH.ui.encabezado(plan ? 'Incorporar recomendaciones al plan' : 'Construir el plan de acción', 'Recomendaciones derivadas de tu autodiagnóstico. Selecciona las que incorporarás como compromisos; podrás editarlas, priorizarlas y añadir acciones propias.') +
      (sug.length ? '<form data-form="plan-generar" novalidate><div class="flex justify-between items-center wrap gap-3 mb-3"><div class="texto-sm texto-2"><strong>' + sug.length + '</strong> recomendaciones · generadas con reglas deterministas a partir de tus respuestas "No implementado", "Parcialmente" y "No sé".</div><div class="flex gap-2"><button type="button" class="btn btn--terciario btn--sm" data-action="plan-sel-todas">Seleccionar todas</button><button type="button" class="btn btn--terciario btn--sm" data-action="plan-sel-ninguna">Ninguna</button></div></div>' +
        instr.dimensiones.map(dim => { const as = sug.filter(a => a.dim === dim.id); if (!as.length) return ''; return '<h2 style="font-size:var(--th-t-lg)" class="mt-4">Dimensión ' + dim.orden + ' · ' + esc(dim.nombre) + '</h2>' + as.map(a => '<label class="card card--compacta mb-3 flex gap-3 items-start" style="cursor:pointer"><input type="checkbox" name="sel" value="' + a.id + '" ' + (ui.seleccionSug.includes(a.id) ? 'checked' : '') + ' style="width:18px;height:18px;margin-top:4px;accent-color:var(--th-primario)"><div class="grow"><div class="flex justify-between gap-3 wrap"><strong>' + esc(a.objetivo) + '</strong><span><span class="prioridad prioridad--' + a.prioridad + '"></span>' + esc(TH.util.nombreCatalogo(cat.prioridades, a.prioridad)) + '</span></div><p class="texto-sm texto-2 mt-1 mb-1"><strong>Situación:</strong> ' + esc(a.situacion) + '</p><p class="texto-sm mb-1"><strong>Acción recomendada:</strong> ' + esc(a.accion) + '</p><div class="texto-xs texto-2">Indicador: ' + esc(a.indicador) + ' · Meta: ' + esc(a.meta) + ' · Evidencia: ' + esc(a.evidencia) + ' · Plazo sugerido: ' + esc(TH.util.fecha(a.fechaObjetivo)) + ' · Fundamento: ' + esc((a.fuentes || []).join(', ')) + '</div></div></label>').join(''); }).join('') +
        '<div class="flex justify-end gap-2 mt-4 wrap">' + (plan ? '<a class="btn btn--terciario" href="#/organizacion/plan-accion">Cancelar</a>' : '') + '<button type="submit" class="btn btn--primario btn--lg">' + (plan ? 'Incorporar seleccionadas' : 'Crear el plan con las seleccionadas') + ' ' + ic('flecha') + '</button></div></form>' : TH.ui.vacio('No hay recomendaciones pendientes', 'Todas las brechas del autodiagnóstico ya están en el plan.', '<a class="btn btn--primario" href="#/organizacion/plan-accion">Volver al plan</a>'));
  }
  function planTabla(acciones) {
    const ev = TH.api.evidencias.listar(orgId());
    return TH.ui.tabla([
      { titulo: 'Acción', render: a => '<a href="#/organizacion/plan-accion/detalle?id=' + a.id + '"><strong>' + esc(a.objetivo) + '</strong></a><div class="texto-xs texto-2 mt-1">' + esc(a.accion.slice(0, 110)) + (a.accion.length > 110 ? '…' : '') + '</div>' },
      { titulo: 'Dimensión', render: a => TH.ui.badge(dimNombre(a.dim), 'turquesa') },
      { titulo: 'Prioridad', render: a => '<span class="prioridad prioridad--' + a.prioridad + '"></span>' + esc(TH.util.nombreCatalogo(cat.prioridades, a.prioridad)) },
      { titulo: 'Responsable', campo: 'responsable' },
      { titulo: 'Fecha objetivo', render: a => (a.fechaObjetivo < TH.util.hoy() && a.estado !== 'completada' ? '<span class="texto-riesgo">' : '<span>') + esc(TH.util.fecha(a.fechaObjetivo)) + '</span>' },
      { titulo: 'Estado', render: a => '<select class="select" style="min-height:34px;min-width:140px;padding:4px 30px 4px 8px;font-size:12px" aria-label="Estado de la acción" data-change="plan-estado" data-id="' + a.id + '">' + cat.estadosAccion.map(e => '<option value="' + e.id + '" ' + (a.estado === e.id ? 'selected' : '') + '>' + esc(e.nombre) + '</option>').join('') + '</select>' },
      { titulo: 'Avance', render: a => TH.ui.progreso(a.avance) },
      { titulo: 'Evid.', clase: 'num', render: a => String(ev.filter(e => e.accionId === a.id).length) },
      { titulo: '', clase: 'acciones', render: a => '<a class="btn btn--terciario btn--sm" href="#/organizacion/plan-accion/detalle?id=' + a.id + '">Detalle</a>' }
    ], acciones, { caption: 'Acciones del plan', vacioTitulo: 'Sin acciones para estos filtros', vacioTexto: 'Cambia los filtros o añade una acción.' });
  }
  function planTablero(acciones) {
    return '<div class="kanban">' + cat.estadosAccion.map(e => { const as = acciones.filter(a => a.estado === e.id); return '<div class="kanban__col"><h4><span>' + esc(e.nombre) + '</span><span>' + as.length + '</span></h4>' + (as.length ? as.map(a => '<div class="kanban__item" role="link" tabindex="0" data-action="ir" data-ruta="/organizacion/plan-accion/detalle?id=' + a.id + '"><div class="kanban__item-titulo"><span class="prioridad prioridad--' + a.prioridad + '"></span>' + esc(a.objetivo) + '</div><div class="kanban__item-meta"><span>' + esc(a.responsable) + '</span><span>' + esc(TH.util.fecha(a.fechaObjetivo)) + '</span></div>' + TH.ui.progreso(a.avance, { sinValor: true }) + '</div>').join('') : '<p class="texto-xs texto-3">Sin acciones</p>') + '</div>'; }).join('') + '</div>';
  }
  function seguimiento() {
    const plan = TH.api.plan.obtener(orgId());
    if (!plan) return TH.ui.encabezado('Seguimiento de compromisos', 'Avance, vencimientos y evidencias del plan de acción.') + TH.ui.vacio('Aún no hay plan de acción', 'Construye el plan para hacer seguimiento a tus compromisos.', '<a class="btn btn--primario" href="#/organizacion/plan-accion">Ir al plan de acción</a>', 'tablero');
    TH.api.plan.actualizarVencidas(orgId());
    const r = TH.api.plan.resumen(plan); const hoy = TH.util.hoy();
    const porResp = {}; plan.acciones.forEach(a => { const k = a.responsable || 'Sin responsable'; porResp[k] = porResp[k] || { total: 0, completadas: 0, vencidas: 0 }; porResp[k].total++; if (a.estado === 'completada') porResp[k].completadas++; if (a.estado !== 'completada' && a.fechaObjetivo < hoy) porResp[k].vencidas++; });
    return TH.ui.encabezado('Seguimiento de compromisos', 'Estado del plan de acción, vencimientos, evidencias y carga por responsable.', '<a class="btn btn--primario" href="#/organizacion/plan-accion">Ir al plan</a><a class="btn btn--secundario" href="#/organizacion/reportes">Reporte</a>') +
      '<div class="grid grid-4 mb-4">' + TH.ui.kpi('Avance global', r.avance + '%', r.total + ' acciones', true) + TH.ui.kpi('Completadas', String(r.completadas)) + TH.ui.kpi('Vencidas', String(r.vencidas.length), 'sin cerrar') + TH.ui.kpi('Próximas 30 días', String(r.proximas.length)) + '</div>' +
      '<div class="grid grid-2"><div class="card"><h3 class="card__titulo">Por estado</h3>' + TH.graficos.barras(cat.estadosAccion.map(e => ({ etiqueta: e.nombre, valor: r.porEstado[e.id], sufijo: '' })), { max: Math.max(1, r.total), sufijo: '' }) + '</div>' +
      '<div class="card"><h3 class="card__titulo">Por responsable</h3>' + TH.ui.tabla([{ titulo: 'Responsable', render: x => esc(x.k) }, { titulo: 'Acciones', clase: 'num', render: x => String(x.v.total) }, { titulo: 'Completadas', clase: 'num', render: x => String(x.v.completadas) }, { titulo: 'Vencidas', clase: 'num', render: x => x.v.vencidas ? TH.ui.badge(String(x.v.vencidas), 'error') : '0' }], Object.keys(porResp).map(k => ({ k, v: porResp[k] })), { caption: 'Carga por responsable' }) + '</div></div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Acciones vencidas</h3>' + (r.vencidas.length ? TH.ui.tabla([{ titulo: 'Acción', render: a => '<a href="#/organizacion/plan-accion/detalle?id=' + a.id + '">' + esc(a.objetivo) + '</a>' }, { titulo: 'Responsable', campo: 'responsable' }, { titulo: 'Venció', render: a => esc(TH.util.fecha(a.fechaObjetivo)) }, { titulo: 'Avance', render: a => TH.ui.progreso(a.avance) }, { titulo: '', clase: 'acciones', render: a => '<button type="button" class="btn btn--terciario btn--sm" data-action="plan-reprogramar" data-id="' + a.id + '">Reprogramar</button>' }], r.vencidas, { caption: 'Vencidas' }) : '<p class="texto-2">No hay acciones vencidas.</p>') + '</div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Próximos vencimientos (30 días)</h3>' + (r.proximas.length ? TH.ui.tabla([{ titulo: 'Acción', render: a => '<a href="#/organizacion/plan-accion/detalle?id=' + a.id + '">' + esc(a.objetivo) + '</a>' }, { titulo: 'Responsable', campo: 'responsable' }, { titulo: 'Fecha', render: a => esc(TH.util.fecha(a.fechaObjetivo)) }, { titulo: 'Estado', render: a => TH.ui.badgeCatalogo(cat.estadosAccion, a.estado) }], r.proximas, { caption: 'Próximas' }) : '<p class="texto-2">Sin vencimientos en los próximos 30 días.</p>') + '</div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Historial del plan</h3>' + TH.ui.historial((plan.historial || []).map(h => ({ fecha: h.fecha, actor: '', accion: h.accion }))) + '</div>';
  }
  function planDetalle(ctx) {
    const plan = TH.api.plan.obtener(orgId()); const a = plan && plan.acciones.find(x => x.id === ctx.params.id);
    if (!a) return TH.ui.vacio('Acción no encontrada', 'La acción solicitada no existe en el plan.', '<a class="btn btn--primario" href="#/organizacion/plan-accion">Volver al plan</a>');
    const preg = a.preguntaId ? instr.preguntas.find(q => q.id === a.preguntaId) : null; const ev = TH.api.evidencias.listar(orgId(), { accionId: a.id });
    return TH.ui.migas([{ texto: 'Plan de acción', ruta: '/organizacion/plan-accion' }, { texto: 'Detalle de acción' }]) +
      TH.ui.encabezado(a.objetivo, TH.ui.badge(dimNombre(a.dim), 'turquesa') + ' ' + TH.ui.badgeCatalogo(cat.estadosAccion, a.estado) + ' ' + TH.ui.badge(a.origen === 'sugerida' ? 'Recomendación del autodiagnóstico' : 'Acción propia', 'neutro'), '<button type="button" class="btn btn--peligro" data-action="plan-eliminar" data-id="' + a.id + '">Eliminar</button>') +
      '<div class="grid grid-sidebar"><div><form class="card" data-form="plan-editar" data-id="' + a.id + '" novalidate>' +
      TH.ui.campo({ name: 'dim', label: 'Dimensión', tipo: 'select', required: true, opciones: instr.dimensiones.map(d => ({ id: d.id, nombre: d.nombre })), valor: a.dim }) +
      TH.ui.campo({ name: 'situacion', label: 'Situación u oportunidad identificada', tipo: 'textarea', rows: 2, valor: a.situacion }) +
      TH.ui.campo({ name: 'objetivo', label: 'Objetivo', required: true, valor: a.objetivo }) +
      TH.ui.campo({ name: 'accion', label: 'Acción concreta', tipo: 'textarea', required: true, valor: a.accion }) +
      '<div class="form-fila--3 form-fila">' + TH.ui.campo({ name: 'prioridad', label: 'Prioridad', tipo: 'select', opciones: cat.prioridades, valor: a.prioridad }) + TH.ui.campo({ name: 'responsable', label: 'Responsable', required: true, valor: a.responsable, ayuda: 'Nombre o cargo.' }) + TH.ui.campo({ name: 'fechaObjetivo', label: 'Fecha objetivo', tipo: 'date', required: true, valor: a.fechaObjetivo }) + '</div>' +
      '<div class="form-fila">' + TH.ui.campo({ name: 'indicador', label: 'Indicador de cumplimiento', required: true, valor: a.indicador }) + TH.ui.campo({ name: 'meta', label: 'Meta', required: true, valor: a.meta }) + '</div>' +
      TH.ui.campo({ name: 'evidencia', label: 'Evidencia organizacional esperada', valor: a.evidencia }) +
      '<div class="form-fila">' + TH.ui.campo({ name: 'estado', label: 'Estado', tipo: 'select', opciones: cat.estadosAccion, valor: a.estado }) + TH.ui.campo({ name: 'avance', label: 'Porcentaje de avance', tipo: 'number', min: 0, max: 100, step: 5, valor: a.avance }) + '</div>' +
      TH.ui.campo({ name: 'observaciones', label: 'Observaciones', tipo: 'textarea', rows: 3, valor: a.observaciones }) +
      '<div class="flex justify-end gap-2 wrap"><a class="btn btn--terciario" href="#/organizacion/plan-accion">Volver</a><button type="button" class="btn btn--secundario" data-action="plan-completar" data-id="' + a.id + '">Marcar completada</button><button type="submit" class="btn btn--primario">Guardar cambios</button></div></form>' +
      '<div class="card mt-4"><div class="card__encabezado"><div><h3 class="card__titulo">Evidencias institucionales</h3><p class="card__sub">Documentos organizacionales que respaldan esta acción (actas, políticas, registros, reportes). No registres datos personales innecesarios ni información sobre casos.</p></div><button type="button" class="btn btn--primario btn--sm" data-action="evidencia-nueva" data-accion="' + a.id + '">' + ic('mas') + ' Registrar evidencia</button></div>' +
      (ev.length ? ev.map(e => TH.ui.evidencia(e, '<button type="button" class="btn btn--terciario btn--sm" data-action="evidencia-eliminar" data-id="' + e.id + '" aria-label="Eliminar ' + esc(e.nombre) + '">Eliminar</button>')).join('') : '<p class="texto-sm texto-2 mb-0">Aún no hay evidencias registradas para esta acción.</p>') + '</div>' +
      (a.bitacora && a.bitacora.length ? '<div class="card mt-4"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Bitácora de cambios</h3>' + TH.ui.historial(a.bitacora.map(b => ({ fecha: b.fecha, actor: '', accion: 'Campos actualizados: ' + b.cambios.join(', ') }))) + '</div>' : '') + '</div>' +
      '<aside>' + (preg ? '<div class="card card--suave"><h4>Origen en el autodiagnóstico</h4><p class="texto-sm">' + esc(preg.texto) + '</p><p class="texto-xs texto-2"><strong>Capacidad:</strong> ' + esc(preg.capacidad) + '</p><strong class="texto-xs">Fundamento</strong>' + TH.ui.referencias(preg.fuentes) + '</div>' : '') +
      '<div class="card mt-4"><h4>Enfoque SMART</h4><ul class="texto-sm texto-2 mb-0"><li><strong>Específica:</strong> una acción concreta y verificable.</li><li><strong>Medible:</strong> indicador y meta.</li><li><strong>Asignable:</strong> responsable con nombre o cargo.</li><li><strong>Realista:</strong> recursos y tiempo disponibles.</li><li><strong>Temporal:</strong> fecha objetivo.</li></ul></div></aside></div>';
  }

  /* ================= COLABORADORES Y SENSIBILIZACIÓN ================= */
  function colaboradores() {
    const agg = TH.api.formacion.agregadosOrganizacion(orgId()); const inv = TH.api.invitaciones.listar(orgId()); const pendientes = inv.filter(i => i.estado === 'pendiente');
    const tabs = TH.ui.tabs([{ id: 'colaboradores', texto: 'Colaboradores vinculados', n: agg.colaboradores }, { id: 'invitaciones', texto: 'Invitaciones', n: inv.length }], ui.colabTab, 'colab-tab');
    let cuerpo;
    if (ui.colabTab === 'colaboradores') {
      cuerpo = TH.ui.tabla([
        { titulo: 'Colaborador', render: c => '<strong>' + esc(c.usuario.nombre) + '</strong><div class="texto-xs texto-2">' + esc(c.usuario.area || '') + '</div>' },
        { titulo: 'Módulos asignados', clase: 'num', render: c => String(c.asignados) }, { titulo: 'Completados', clase: 'num', render: c => String(c.completados) }, { titulo: 'En curso', clase: 'num', render: c => String(c.enCurso) },
        { titulo: 'Pendientes', clase: 'num', render: c => c.pendientes ? TH.ui.badge(String(c.pendientes), 'alerta') : TH.ui.badge('0', 'exito') },
        { titulo: 'Avance', render: c => TH.ui.progreso(c.pct, { color: 'naranja' }) },
        { titulo: '', clase: 'acciones', render: c => '<button type="button" class="btn btn--terciario btn--sm" data-action="colab-asignar-usuario" data-user="' + c.usuario.id + '">Módulos</button> <button type="button" class="btn btn--terciario btn--sm" data-action="colab-desvincular" data-user="' + c.usuario.id + '">Desvincular</button>' }
      ], agg.porColaborador, { caption: 'Colaboradores vinculados', vacioTitulo: 'Aún no hay colaboradores', vacioTexto: 'Crea invitaciones para que tu equipo acceda a los módulos de sensibilización.' }) +
        '<p class="texto-xs texto-3 mt-3">Por protección de datos, solo se muestran estados de avance. Las respuestas de los ejercicios son individuales y no se exponen a la organización.</p>';
    } else {
      cuerpo = TH.ui.tabla([
        { titulo: 'Persona', render: i => '<strong>' + esc(i.nombre) + '</strong><div class="texto-xs texto-2">' + esc(i.email) + '</div>' },
        { titulo: 'Código', render: i => '<code>' + esc(i.codigo) + '</code>' },
        { titulo: 'Módulos', render: i => i.modulos.length ? i.modulos.map(m => TH.ui.badge('M' + m.replace('mod-', ''), 'naranja')).join(' ') : TH.ui.badge('Sin asignar', 'alerta') },
        { titulo: 'Estado', render: i => i.estado === 'activada' ? TH.ui.badge('Activada', 'exito') : i.estado === 'anulada' ? TH.ui.badge('Anulada', 'neutro') : (i.expira && i.expira < TH.util.hoy() ? TH.ui.badge('Expirada', 'error') : TH.ui.badge('Pendiente', 'alerta')) },
        { titulo: 'Envío', render: i => i.estado === 'pendiente' ? (i.envio === 'enviado' ? TH.ui.badge('Correo enviado', 'exito') : TH.ui.badge('Compartir código', 'info')) : '—' },
        { titulo: 'Expira', render: i => esc(TH.util.fecha(i.expira)) },
        { titulo: '', clase: 'acciones', render: i => i.estado === 'pendiente' ? '<button type="button" class="btn btn--terciario btn--sm" data-action="colab-asignar" data-inv="' + i.id + '">Módulos</button> <button type="button" class="btn btn--terciario btn--sm" data-action="colab-reenviar" data-inv="' + i.id + '">Reenviar</button> <button type="button" class="btn btn--terciario btn--sm" data-action="colab-anular-inv" data-inv="' + i.id + '">Anular</button>' : '' }
      ], inv, { caption: 'Invitaciones', vacioTitulo: 'Sin invitaciones', vacioTexto: 'Crea la primera invitación.' }) +
        TH.ui.alerta('info', 'Cómo activa su acceso un colaborador', 'Cada persona invitada recibe un enlace y un código. Con ellos crea su contraseña en <a href="#/activar-invitacion">Activar invitación</a> y accede únicamente a los módulos que le asignaste. Las invitaciones expiran a los 30 días.');
    }
    return TH.ui.encabezado('Colaboradores', 'Invita a tu equipo, asigna módulos de sensibilización y consulta indicadores agregados de participación.', '<button type="button" class="btn btn--primario" data-action="colab-invitar">' + ic('mas') + ' Crear invitación</button>') +
      '<div class="grid grid-4 mb-4">' + TH.ui.kpi('Vinculados', String(agg.colaboradores), pendientes.length + ' invitaciones pendientes') + TH.ui.kpi('Cobertura', agg.coberturaPct + '%', agg.totalCompletados + ' de ' + agg.totalAsignaciones + ' módulos asignados completados', true) + TH.ui.kpi('Con al menos un módulo', String(agg.colaboradoresConAlMenosUno), 'colaboradores') + TH.ui.kpi('Módulos pendientes', String(agg.porModulo.reduce((t, m) => t + m.pendientes, 0)), 'sin iniciar') + '</div>' + tabs + cuerpo;
  }
  function sensibilizacion() {
    const agg = TH.api.formacion.agregadosOrganizacion(orgId());
    return TH.ui.encabezado('Sensibilización de colaboradores', 'Cobertura y participación agregadas por módulo. Sin respuestas individuales.', '<a class="btn btn--primario" href="#/organizacion/colaboradores">Gestionar colaboradores</a>') +
      '<div class="grid grid-2">' + agg.porModulo.map(m => '<div class="card"><div class="modulo-card"><div class="modulo-card__num modulo-card__num--' + m.modulo.color + '">' + m.modulo.orden + '</div><div><h3 class="card__titulo">' + esc(m.modulo.titulo) + '</h3><p class="card__sub">' + esc(m.modulo.resumen) + '</p><ul class="texto-sm texto-2 mt-2">' + (m.modulo.objetivos || []).slice(0, 3).map(x => '<li>' + esc(x) + '</li>').join('') + '</ul><div class="mt-3">' + TH.ui.progreso(m.pct, { etiqueta: m.completados + '/' + m.asignados + ' completados', color: 'naranja' }) + '</div><div class="texto-xs texto-2 mt-2">' + m.enCurso + ' en curso · ' + m.pendientes + ' pendientes · ' + esc(m.modulo.duracion) + ' · ' + m.modulo.lecciones.length + ' lecciones · ' + m.modulo.quiz.length + ' preguntas</div><details class="ayuda"><summary>Bibliografía del módulo</summary><div class="ayuda__cuerpo">' + TH.ui.referencias(m.modulo.bibliografia) + '</div></details></div></div></div>').join('') + '</div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Módulos pendientes por colaborador</h3>' + (agg.porColaborador.filter(c => c.pendientes > 0).length ? '<ul class="texto-sm">' + agg.porColaborador.filter(c => c.pendientes > 0).map(c => '<li>' + esc(c.usuario.nombre) + ': ' + c.pendientes + ' pendiente(s)</li>').join('') + '</ul>' : '<p class="texto-2">Todos los colaboradores han iniciado sus módulos asignados.</p>') + '</div>' +
      TH.ui.alerta('neutra', 'Constancias', 'Las constancias que genera la plataforma acreditan la participación en una actividad formativa; no son certificaciones profesionales.');
  }

  /* ================= BIBLIOTECA ================= */
  function biblioteca(ctx, publico) {
    const pub = publico || 'organizacion'; const base = ctx.ruta;
    if (ctx.params.id) {
      const c = TH.api.contenidos.obtener(ctx.params.id);
      if (!TH.api.contenidos.esVisible(c, pub)) return TH.ui.vacio('Recurso no disponible', 'Este contenido no está publicado para tu perfil o no existe.', '<a class="btn btn--primario" href="#' + base + '">Volver a la biblioteca</a>');
      return TH.ui.migas([{ texto: 'Biblioteca', ruta: base }, { texto: c.titulo }]) + fichaContenido(c);
    }
    const lista = TH.api.contenidos.visibles(pub, { q: ui.bibliotecaQ, categoria: ui.bibliotecaCat, tema: ui.bibliotecaTema });
    const temas = [...new Set(TH.api.contenidos.visibles(pub).map(c => c.tema))].sort();
    return TH.ui.encabezado('Biblioteca de herramientas y contenidos', 'Guías prácticas, modelos orientativos, herramientas, glosario y fichas normativas con fuentes verificables. Los contenidos pasan por revisión técnica, jurídica y psicosocial antes de publicarse.') +
      '<div class="filtros"><div class="buscador campo">' + ic('lupa') + '<label class="sr-only" for="bq">Buscar</label><input class="input" id="bq" type="search" placeholder="Buscar por título, tema o palabra clave" value="' + esc(ui.bibliotecaQ) + '" data-input="biblioteca-q"></div>' +
      '<div class="campo"><label class="sr-only" for="bc">Categoría</label><select class="select" id="bc" data-change="biblioteca-cat"><option value="">Todas las categorías</option>' + cat.categoriasContenido.map(c => '<option ' + (ui.bibliotecaCat === c ? 'selected' : '') + '>' + esc(c) + '</option>').join('') + '</select></div>' +
      '<div class="campo"><label class="sr-only" for="bt">Tema</label><select class="select" id="bt" data-change="biblioteca-tema"><option value="">Todos los temas</option>' + temas.map(t => '<option ' + (ui.bibliotecaTema === t ? 'selected' : '') + '>' + esc(t) + '</option>').join('') + '</select></div></div>' +
      (lista.length ? '<div class="grid grid-3">' + lista.map(c => '<a class="card card--compacta" href="#' + base + '?id=' + c.id + '"><div class="mb-2">' + TH.ui.badge(c.categoria, 'violeta') + '</div><h3 class="card__titulo" style="font-size:var(--th-t-md)">' + esc(c.titulo) + '</h3><p class="card__sub">' + esc(c.descripcion) + '</p>' + (c.referencial ? '<div class="mt-2"><span class="etiqueta etiqueta--referencial">Modelo orientativo</span></div>' : '') + '<div class="texto-xs texto-3 mt-3">' + esc(c.tema) + ' · ' + (c.tiempoLectura ? c.tiempoLectura + ' min · ' : '') + 'v' + esc(c.version) + ' · ' + esc(TH.util.fecha(c.fecha)) + '</div></a>').join('') + '</div>' :
        (TH.api.contenidos.visibles(pub).length ? TH.ui.vacio('Sin resultados', 'No hay recursos publicados que coincidan con tu búsqueda.', '', 'lupa') : TH.ui.vacio('Aún no hay contenidos publicados', 'Los recursos de la biblioteca se publican únicamente cuando la Fundación Milagro de Abril ha registrado las revisiones técnica, jurídica y psicosocial aplicables. En este momento no hay contenidos publicados para tu perfil.', '', 'biblioteca')));
  }
  function fichaContenido(c) {
    const sec = (c.secciones || []).map(s => '<section class="mt-5"><h2 style="font-size:var(--th-t-lg)">' + esc(s.titulo) + '</h2>' + (s.cuerpo || []).map(p => '<p>' + esc(p) + '</p>').join('') + (s.lista && s.lista.length ? '<ul>' + s.lista.map(l => '<li>' + esc(l) + '</li>').join('') + '</ul>' : '') + '</section>').join('');
    return '<article class="card" style="max-width:860px"><div class="mb-2">' + TH.ui.badge(c.categoria, 'violeta') + ' ' + TH.ui.badge(c.tema, 'neutro') + (c.tiempoLectura ? ' ' + TH.ui.badge(c.tiempoLectura + ' min de lectura', 'neutro') : '') + '</div><h1 style="font-size:var(--th-t-2xl)">' + esc(c.titulo) + '</h1><p class="texto-2">' + esc(c.descripcion) + '</p>' + (c.referencial ? '<p>' + TH.ui.referencial() + '</p>' : '') +
      (c.objetivo ? '<section class="mt-4"><h2 style="font-size:var(--th-t-lg)">Objetivo</h2><p>' + esc(c.objetivo) + '</p></section>' : '') + sec +
      '<section class="mt-5"><h2 style="font-size:var(--th-t-lg)">Referencias</h2>' + TH.ui.referencias(c.referencias) + '</section>' +
      '<hr>' + TH.ui.dl([['Responsable', c.autor], ['Fecha de revisión', TH.util.fecha(c.revision ? c.revision.fecha : c.fecha)], ['Versión', c.version], ['Estado editorial', TH.util.nombreCatalogo(cat.estadosContenido, c.estado)], ['Revisión técnica', TH.util.nombreCatalogo(cat.estadosRevision, c.revisionTecnica)], ['Revisión jurídica', TH.util.nombreCatalogo(cat.estadosRevision, c.revisionJuridica)], ['Revisión psicosocial', TH.util.nombreCatalogo(cat.estadosRevision, c.revisionPsicosocial || 'no-aplica')]].concat(c.fuente ? [['Fuente principal', c.fuente], ['Fecha de verificación', c.fechaVerificacion || 'Pendiente'], ['Responsable de verificación', c.responsableVerificacion || 'Pendiente']] : [])) + '</article>';
  }
  TH.vistasCompartidas = TH.vistasCompartidas || {}; TH.vistasCompartidas.biblioteca = biblioteca; TH.vistasCompartidas.fichaContenido = fichaContenido;

  /* ================= SELLO, REPORTES, CUENTA ================= */
  function sello() {
    const o = org(); const intereses = TH.api.sello.interesesDeOrganizacion(o.id);
    return TH.ui.encabezado('Sello Turquesa', 'Servicio de evaluación, acompañamiento y reconocimiento organizacional de Fundación Milagro de Abril. Turquesa Hub es su plataforma de preparación.') +
      '<div class="sello-marca"><img class="sello-marca__logo" src="assets/branding/sello-turquesa-imagotipo.png" alt="Sello Turquesa" width="1600" height="629"><div class="sello-marca__texto"><strong>Sello Turquesa · Un servicio de Fundación Milagro de Abril</strong>Una organización atendida no adquiere automáticamente el derecho a usar el Sello: solo lo exhibe quien cumple los criterios técnicos, completa el procedimiento y recibe autorización expresa.</div></div>' +
      '<div class="grid grid-2"><div><div class="card"><h3>Qué es y cómo se relaciona con tu gestión</h3><p>El Sello Turquesa reconoce a organizaciones que estructuran, ejecutan y evidencian su gestión de prevención de las violencias basadas en género. Sus dimensiones coinciden con las del autodiagnóstico: compromiso y gobernanza, cultura e igualdad, políticas y protocolos, formación, canales y articulación, y seguimiento.</p><p>Tu trabajo en Turquesa Hub (autodiagnóstico, plan de acción con evidencias, sensibilización y reportes) es la preparación natural para postularte cuando la Fundación abra el proceso.</p><h4 class="mt-4">Cómo prepararse desde hoy</h4><ol class="texto-sm"><li>Completa el autodiagnóstico y construye el plan de acción.</li><li>Registra las evidencias institucionales de cada acción.</li><li>Forma a tu equipo con los módulos de sensibilización.</li><li>Manifiesta tu interés: la FMA te informará la apertura del proceso.</li></ol><a class="btn btn--secundario" href="#/sello-turquesa">Ver la presentación pública del Sello</a></div>' +
      (intereses.length ? '<div class="card card--suave mt-4"><h4>Manifestaciones de tu organización</h4>' + intereses.map(i => '<p class="texto-sm mb-1">' + esc(TH.util.fecha(i.fecha)) + ' · ' + esc(i.contacto) + ' · ' + TH.ui.badgeCatalogo(cat.estadosInteres, i.estado) + '</p>').join('') + '</div>' : '') + '</div>' +
      '<div>' + TH.vistasCompartidas.formularioInteres('so-', o, TH.auth.usuario()) + '</div></div>';
  }
  function reportes() {
    const r = TH.api.reportes.organizacion(orgId()); const o = r.org;
    return '<div class="no-imprimir">' + TH.ui.encabezado('Reportes institucionales', 'Reporte consolidado de la gestión preventiva. Usa "Descargar PDF" (imprimir → guardar como PDF) para compartirlo.', '<button type="button" class="btn btn--primario" data-action="imprimir">' + ic('imprimir') + ' Descargar PDF</button>' + (r.plan ? '<button type="button" class="btn btn--secundario" data-action="plan-descargar-csv">' + ic('descargar') + ' Plan en CSV</button>' : '')) + '</div>' +
      '<div class="reporte"><div class="reporte__portada card"><div class="flex justify-between wrap gap-3"><div><div class="seccion__eyebrow">Turquesa Hub · Reporte institucional</div><h1 style="font-size:var(--th-t-2xl)">' + esc(o.nombre) + '</h1><p class="texto-2">' + esc(o.sector) + ' · ' + esc(o.municipio) + ', ' + esc(o.departamento) + ' · ' + esc(TH.util.nombreCatalogo(cat.tamanos, o.tamano)) + '</p></div><div class="text-right texto-sm texto-2">Generado: ' + esc(TH.util.fechaLarga(r.generado)) + '<br>Responsable: ' + esc(o.responsable) + '</div></div></div>' +
      '<section class="reporte__seccion card mt-4"><h2>1. Autodiagnóstico (resultados declarados)</h2>' + (r.diag && r.diag.estado === 'completado' ? '<p>Completado el ' + esc(TH.util.fecha(r.diag.fechaFin)) + ' con el instrumento v' + esc(r.diag.instrumentoVersion) + ' (ciclo ' + (r.diag.ciclo || 1) + '). Valor orientativo global: <strong>' + r.resultado.global + '%</strong> (' + esc(r.resultado.nivelGlobal.nombre) + '). Fortalezas declaradas: ' + r.resultado.fortalezas.length + ' (' + r.resultado.conEvidencia + ' con evidencia registrada). Esta lectura resume lo declarado por la organización; no constituye evaluación validada, cumplimiento legal ni certificación.</p>' + r.resultado.dimensiones.map(x => '<div class="dimension-fila"><span class="dimension-fila__nombre">' + esc(x.dim.nombre) + '</span>' + TH.ui.progreso(x.puntaje || 0, { sinValor: true, aria: x.dim.nombre }) + '<strong>' + (x.puntaje === null ? 'N/A' : x.puntaje + '%') + '</strong>' + TH.ui.badgeNivel(x.nivel) + '</div>').join('') : '<p class="texto-2">Autodiagnóstico no completado.</p>') + '</section>' +
      '<section class="reporte__seccion card mt-4"><h2>2. Brechas y recomendaciones</h2>' + (r.resultado.brechas.length ? '<ul>' + r.resultado.brechas.map(b => '<li><strong>' + esc(b.dim.corto) + ':</strong> ' + esc(b.pregunta.accion.objetivo) + '</li>').join('') + '</ul>' : '<p class="texto-2">Sin brechas identificadas o sin autodiagnóstico.</p>') + (r.resultado.dimensiones.length ? '<ol>' + TH.api.diagnostico.recomendaciones(r.resultado).map(x => '<li><strong>' + esc(x.dim.nombre) + '.</strong> ' + esc(x.texto) + '</li>').join('') + '</ol>' : '') + '</section>' +
      '<section class="reporte__seccion card mt-4"><h2>3. Plan de acción y seguimiento</h2>' + (r.plan ? '<p>' + r.planResumen.total + ' acciones · avance global ' + r.planResumen.avance + '% · ' + r.planResumen.completadas + ' completadas · ' + r.planResumen.vencidas.length + ' vencidas · ' + r.planResumen.conEvidencia + ' con evidencia registrada.</p>' + TH.ui.tabla([{ titulo: 'Objetivo', campo: 'objetivo' }, { titulo: 'Dimensión', render: a => esc(dimNombre(a.dim)) }, { titulo: 'Responsable', campo: 'responsable' }, { titulo: 'Fecha', render: a => esc(TH.util.fecha(a.fechaObjetivo)) }, { titulo: 'Estado', render: a => TH.ui.badgeCatalogo(cat.estadosAccion, a.estado) }, { titulo: 'Avance', clase: 'num', render: a => a.avance + '%' }], r.plan.acciones, { caption: 'Acciones del plan' }) : '<p class="texto-2">Sin plan de acción.</p>') + '</section>' +
      '<section class="reporte__seccion card mt-4"><h2>4. Sensibilización</h2><p>' + r.formacion.colaboradores + ' colaboradores vinculados · cobertura ' + r.formacion.coberturaPct + '% · ' + r.formacion.totalCompletados + ' módulos completados de ' + r.formacion.totalAsignaciones + ' asignados.</p>' + TH.graficos.barras(r.formacion.porModulo.map(m => ({ etiqueta: 'M' + m.modulo.orden + ' ' + m.modulo.titulo, valor: m.pct }))) + '<p class="texto-xs texto-3 mt-3">Indicadores agregados; no se incluyen datos personales ni respuestas individuales.</p></section>' +
      '<section class="reporte__seccion card mt-4"><h2>5. Evidencias registradas</h2>' + (r.evidencias.length ? TH.ui.tabla([{ titulo: 'Documento', campo: 'nombre' }, { titulo: 'Tipo', campo: 'tipo' }, { titulo: 'Acción', render: e => { const a = r.plan && r.plan.acciones.find(x => x.id === e.accionId); return esc(a ? a.objetivo : '—'); } }, { titulo: 'Fecha', render: e => esc(TH.util.fecha(e.fecha)) }], r.evidencias, { caption: 'Evidencias' }) : '<p class="texto-2">Sin evidencias registradas.</p>') + '</section>' +
      '<p class="texto-xs texto-3 mt-4">Turquesa Hub · Fundación Milagro de Abril · Esta plataforma no recibe denuncias ni gestiona casos individuales.</p></div>';
  }
  function configuracion() {
    const o = org(); const u = TH.auth.usuario();
    return TH.ui.encabezado('Cuenta y datos', 'Credenciales, consentimientos registrados y exportación de la información de tu organización.') +
      '<div class="grid grid-2"><form class="card" data-form="cambiar-clave" novalidate><h3 class="card__titulo">Cambiar contraseña</h3>' + TH.ui.campo({ name: 'actual', label: 'Contraseña actual', tipo: 'password', required: true, attrs: ' autocomplete="current-password"' }) + TH.ui.campo({ name: 'nueva', label: 'Nueva contraseña', tipo: 'password', required: true, ayuda: 'Mínimo ' + TH.config.auth.clave.longitudMinima + ' caracteres, con letras y números.', attrs: ' autocomplete="new-password"' }) + TH.ui.campo({ name: 'confirmacion', label: 'Confirmar nueva contraseña', tipo: 'password', required: true, attrs: ' autocomplete="new-password"' }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div><button type="submit" class="btn btn--primario">Actualizar contraseña</button></form>' +
      '<div><div class="card"><h3 class="card__titulo">Consentimientos registrados</h3>' + ((u && u.consentimientos && u.consentimientos.length) ? '<ul class="texto-sm">' + u.consentimientos.map(c => '<li>' + esc(TH.util.nombreCatalogo(cat.tiposDocumentoLegal, c.tipo)) + ' · versión ' + esc(c.version) + ' · ' + esc(TH.util.fecha(c.fecha)) + (c.modo === 'informado' ? ' · informado' : ' · autorización registrada') + (c.transitorio ? ' · aviso transitorio' : '') + (c.validado === false ? ' · versión de prueba sin validar' : '') + '</li>').join('') + '</ul>' : '<p class="texto-2 texto-sm">Sin consentimientos registrados.</p>') + '<p class="texto-xs texto-2">Consulta el <a href="#/aviso-registro">aviso de información</a> y las versiones vigentes en <a href="#/condiciones">Condiciones de uso</a> y <a href="#/privacidad">Tratamiento de datos</a>.</p></div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Datos de la organización</h3><p class="texto-sm texto-2">Exporta la información de tu organización (perfil, autodiagnóstico, plan, evidencias y participación agregada) en formato JSON.</p><button type="button" class="btn btn--secundario" data-action="exportar-json">' + ic('descargar') + ' Exportar mis datos</button><p class="texto-xs texto-2 mt-3">Para solicitar la supresión de la cuenta o el ejercicio de otros derechos sobre tus datos, escribe a la Fundación Milagro de Abril por el canal indicado en la <a href="#/privacidad">política de tratamiento de datos</a>.</p></div>' +
      '<div class="card mt-4"><h4>Usuarios con acceso</h4>' + TH.ui.tabla([{ titulo: 'Nombre', campo: 'nombre' }, { titulo: 'Correo', campo: 'email' }, { titulo: 'Rol', render: x => TH.ui.badge(TH.util.nombreCatalogo(cat.rolesSistema, x.rol), x.rol === 'colaborador' ? 'naranja' : 'turquesa') }, { titulo: 'Estado', render: x => esc(x.estado || 'activo') }], TH.api.usuarios.listar({ orgId: o.id }), { caption: 'Usuarios de la organización' }) + '</div></div></div>';
  }

  /* ================= MANEJADORES (operaciones asíncronas: funcionan igual con el adaptador local y con la API) ================= */
  const modulosPublicados = () => TH.api.formacion.modulos();
  function listaModulosCheck(seleccionados) {
    const mods = modulosPublicados();
    if (!mods.length) return TH.ui.alerta('info', 'Sin módulos publicados', 'La Fundación Milagro de Abril aún no ha publicado módulos de sensibilización. Podrás asignarlos cuando estén disponibles.');
    return '<fieldset><legend class="texto-sm">Módulos a asignar</legend>' + mods.map(m => TH.ui.check('modulos', 'Módulo ' + m.orden + ': ' + esc(m.titulo) + ' <span class="texto-2">(' + esc(m.duracion) + ')</span>', seleccionados ? seleccionados.includes(m.id) : true, m.id)).join('') + '</fieldset>';
  }
  Object.assign(TH.acciones, {
    async 'org-iniciar-onboarding'(el) { await TH.api.organizaciones.marcarOnboarding(orgId(), 'bienvenida'); TH.router.ir(el.dataset.ruta); },
    async 'diag-iniciar'(el) { const r = await TH.ui.ejecutar(el, () => TH.api.diagnostico.iniciar(orgId()), { texto: 'Preparando…' }); if (r.ok) TH.router.refrescar(); },
    'diag-ir'(el) { const i = parseInt(el.dataset.indice, 10); if (isNaN(i)) return; TH.api.diagnostico.irA(orgId(), i); TH.router.ir('/organizacion/diagnostico?revisar=1&sinScroll=1'); setTimeout(() => { const t = document.getElementById('pregunta-texto'); if (t) { t.setAttribute('tabindex', '-1'); t.focus(); } }, 0); },
    async 'diag-guardar-salir'() { const f = document.querySelector('form[data-form=diag-responder]'); if (f && f.elements.opcion.value) await TH.formularios['diag-responder'](f, null, true); TH.ui.toast('Progreso guardado.', 'exito'); TH.router.ir('/organizacion/inicio'); },
    async 'diag-finalizar'(el) { const r = await TH.ui.ejecutar(el, () => TH.api.diagnostico.finalizar(orgId()), { texto: 'Calculando…', exito: 'Autodiagnóstico completado.' }); if (r.ok) TH.router.ir('/organizacion/diagnostico/resultados'); },
    async 'diag-nuevo-ciclo'(el) { if (await TH.ui.confirmar({ titulo: 'Iniciar nuevo ciclo', texto: 'El autodiagnóstico actual quedará archivado como línea base y comenzarás uno nuevo. El plan de acción se conserva. ¿Continuar?' })) { const r = await TH.ui.ejecutar(el, () => TH.api.diagnostico.reiniciar(orgId()), { exito: 'Nuevo ciclo iniciado.' }); if (r.ok) TH.router.refrescar(); } },
    'plan-sel-todas'() { const f = document.querySelector('form[data-form=plan-generar]'); f.querySelectorAll('input[name=sel]').forEach(c => c.checked = true); },
    'plan-sel-ninguna'() { const f = document.querySelector('form[data-form=plan-generar]'); f.querySelectorAll('input[name=sel]').forEach(c => c.checked = false); },
    'plan-vista'(el) { ui.planVista = el.dataset.vista; TH.router.refrescar(); },
    'plan-nueva-accion'() {
      TH.ui.modal({ titulo: 'Añadir acción al plan', grande: true, cuerpo: '<form id="form-nueva-accion" data-form="plan-nueva" novalidate>' + TH.ui.campo({ name: 'dim', label: 'Dimensión', tipo: 'select', required: true, opciones: instr.dimensiones.map(d => ({ id: d.id, nombre: d.nombre })), placeholder: 'Selecciona' }) + TH.ui.campo({ name: 'situacion', label: 'Situación u oportunidad', tipo: 'textarea', rows: 2 }) + TH.ui.campo({ name: 'objetivo', label: 'Objetivo', required: true }) + TH.ui.campo({ name: 'accion', label: 'Acción concreta', tipo: 'textarea', required: true }) + '<div class="form-fila--3 form-fila">' + TH.ui.campo({ name: 'prioridad', label: 'Prioridad', tipo: 'select', opciones: cat.prioridades, valor: 'media' }) + TH.ui.campo({ name: 'responsable', label: 'Responsable', required: true }) + TH.ui.campo({ name: 'fechaObjetivo', label: 'Fecha objetivo', tipo: 'date', required: true, valor: TH.util.sumarDias(TH.util.hoy(), 90) }) + '</div><div class="form-fila">' + TH.ui.campo({ name: 'indicador', label: 'Indicador', required: true }) + TH.ui.campo({ name: 'meta', label: 'Meta', required: true }) + '</div>' + TH.ui.campo({ name: 'evidencia', label: 'Evidencia esperada' }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-nueva-accion" class="btn btn--primario">Añadir acción</button>' });
    },
    async 'plan-completar'(el) { const r = await TH.ui.ejecutar(el, () => TH.api.plan.actualizarAccion(orgId(), el.dataset.id, { estado: 'completada', avance: 100 }), { exito: 'Acción marcada como completada.' }); if (r.ok) TH.router.refrescar(); },
    'plan-reprogramar'(el) { TH.ui.modal({ titulo: 'Reprogramar acción', cuerpo: '<form id="form-reprog" data-form="plan-reprogramar" data-id="' + esc(el.dataset.id) + '" novalidate>' + TH.ui.campo({ name: 'fechaObjetivo', label: 'Nueva fecha objetivo', tipo: 'date', required: true, valor: TH.util.sumarDias(TH.util.hoy(), 30) }) + TH.ui.campo({ name: 'observaciones', label: 'Motivo de la reprogramación', tipo: 'textarea', rows: 2, required: true }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-reprog" class="btn btn--primario">Reprogramar</button>' }); },
    async 'plan-eliminar'(el) { if (await TH.ui.confirmar({ titulo: 'Eliminar acción', texto: 'Esta acción y sus evidencias vinculadas se eliminarán del plan. ¿Continuar?', peligro: true, aceptar: 'Eliminar' })) { const r = await TH.ui.ejecutar(el, () => TH.api.plan.eliminarAccion(orgId(), el.dataset.id), { exito: 'Acción eliminada.' }); if (r.ok) TH.router.ir('/organizacion/plan-accion'); } },
    'plan-descargar-csv'() { const plan = TH.api.plan.obtener(orgId()); if (!plan) return; TH.ui.descargar('plan-accion-' + TH.util.hoy() + '.csv', TH.api.plan.aCSV(plan), 'text/csv;charset=utf-8'); TH.ui.toast('CSV generado.', 'exito'); },
    'evidencia-nueva'(el) { const lim = TH.config.archivos; TH.ui.modal({ titulo: 'Registrar evidencia institucional', cuerpo: '<form id="form-evi" data-form="evidencia-nueva" data-accion="' + esc(el.dataset.accion) + '" novalidate>' + TH.ui.campo({ name: 'nombre', label: 'Nombre del documento', required: true, placeholder: 'Ej.: Politica-prevencion-2026.pdf' }) + TH.ui.campo({ name: 'tipo', label: 'Tipo de evidencia', tipo: 'select', required: true, opciones: cat.tiposEvidencia, placeholder: 'Selecciona' }) + TH.ui.campo({ name: 'descripcion', label: 'Descripción breve', tipo: 'textarea', rows: 2 }) + '<div class="campo"><label class="campo__label" for="evi-archivo">Archivo (opcional)</label><input class="input" type="file" id="evi-archivo" name="archivo" accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg"><span class="campo__ayuda">PDF, Word, Excel o imagen, hasta ' + Math.round(lim.maxBytes / 1048576) + ' MB. ' + (TH.config.esRemoto ? 'Se guarda en el almacenamiento protegido de la plataforma.' : 'En el entorno de desarrollo no hay almacenamiento de archivos: se registra la referencia documental (nombre, tipo y tamaño).') + '</span><span class="campo__error" role="alert"></span></div>' + TH.ui.alerta('neutra', '', 'Registra documentos organizacionales. No incluyas datos personales innecesarios ni información sobre casos individuales.') + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-evi" class="btn btn--primario">Registrar</button>' }); },
    async 'evidencia-eliminar'(el) { if (await TH.ui.confirmar({ titulo: 'Eliminar evidencia', texto: 'Se eliminará el registro de la evidencia.', peligro: true, aceptar: 'Eliminar' })) { const r = await TH.ui.ejecutar(el, () => TH.api.evidencias.eliminar(orgId(), el.dataset.id)); if (r.ok) TH.router.refrescar(); } },
    'colab-tab'(el) { ui.colabTab = el.dataset.tab; TH.router.refrescar(); },
    'colab-invitar'() { const hay = modulosPublicados().length > 0; TH.ui.modal({ titulo: 'Crear invitación', cuerpo: '<form id="form-inv" data-form="colab-invitar" novalidate>' + TH.ui.campo({ name: 'nombre', label: 'Nombre de la persona', required: true }) + TH.ui.campo({ name: 'email', label: 'Correo', tipo: 'email', required: true }) + TH.ui.campo({ name: 'area', label: 'Área o equipo (opcional)' }) + listaModulosCheck(null) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div><p class="texto-xs texto-2">La persona recibirá un enlace y un código para crear su contraseña. Solo verá los módulos asignados' + (hay ? '' : ' (podrás asignarlos cuando haya módulos publicados)') + '.</p></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-inv" class="btn btn--primario">Crear invitación</button>' }); },
    'colab-asignar'(el) { const inv = TH.api.invitaciones.listar(orgId()).find(i => i.id === el.dataset.inv); if (!inv) return; TH.ui.modal({ titulo: 'Asignar módulos · ' + inv.nombre, cuerpo: '<form id="form-asig" data-form="colab-asignar" data-inv="' + inv.id + '" novalidate>' + listaModulosCheck(inv.modulos) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-asig" class="btn btn--primario">Guardar</button>' }); },
    'colab-asignar-usuario'(el) { const u = TH.api.usuarios.obtener(el.dataset.user); if (!u) return; const actuales = TH.api.formacion.asignados(u.id).map(m => m.id); TH.ui.modal({ titulo: 'Asignar módulos · ' + u.nombre, cuerpo: '<form id="form-asig-u" data-form="colab-asignar-usuario" data-user="' + u.id + '" novalidate>' + listaModulosCheck(actuales) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-asig-u" class="btn btn--primario">Guardar</button>' }); },
    async 'colab-reenviar'(el) { const r = await TH.ui.ejecutar(el, () => TH.api.invitaciones.reenviar(el.dataset.inv), { exito: TH.config.esRemoto ? 'Invitación reenviada por correo.' : 'Vigencia de la invitación renovada. Comparte el código con la persona.' }); if (r.ok) TH.router.refrescar(); },
    async 'colab-anular-inv'(el) { if (await TH.ui.confirmar({ titulo: 'Anular invitación', texto: 'La invitación dejará de ser válida.', peligro: true, aceptar: 'Anular' })) { const r = await TH.ui.ejecutar(el, () => TH.api.invitaciones.anular(el.dataset.inv)); if (r.ok) TH.router.refrescar(); } },
    async 'colab-desvincular'(el) { if (await TH.ui.confirmar({ titulo: 'Desvincular colaborador', texto: 'La persona perderá el acceso a los módulos asignados por tu organización. Su progreso personal se conserva de forma privada.', peligro: true, aceptar: 'Desvincular' })) { const r = await TH.ui.ejecutar(el, () => TH.api.invitaciones.desvincular(orgId(), el.dataset.user)); if (r.ok) TH.router.refrescar(); } },
    async 'exportar-json'(el) {
      if (TH.config.esRemoto) { const r = await TH.ui.ejecutar(el, () => TH.http.descargar('/organizaciones/mia/exportacion', 'turquesa-hub-' + orgId() + '-' + TH.util.hoy() + '.json'), { texto: 'Generando…', exito: 'Exportación generada.' }); return r; }
      const id = orgId(); const datos = { organizacion: TH.api.organizaciones.obtener(id), autodiagnostico: TH.api.diagnostico.obtener(id), plan: TH.api.plan.obtener(id), evidencias: TH.api.evidencias.listar(id), participacionAgregada: TH.api.formacion.agregadosOrganizacion(id).porModulo, exportado: new Date().toISOString() };
      TH.ui.descargar('turquesa-hub-' + id + '-' + TH.util.hoy() + '.json', JSON.stringify(datos, null, 2), 'application/json'); TH.ui.toast('Exportación generada.', 'exito');
    }
  });
  Object.assign(TH.cambios, {
    'diag-opcion'(el) { const j = document.getElementById('diag-justificacion'); if (j) j.classList.toggle('hidden', el.value !== 'na'); },
    async 'plan-estado'(el) { const cambios = { estado: el.value }; if (el.value === 'completada') cambios.avance = 100; el.disabled = true; const r = await TH.api.plan.actualizarAccion(orgId(), el.dataset.id, cambios); el.disabled = false; if (!r.ok) { TH.ui.errorApi(r); TH.router.refrescar(); return; } TH.ui.toast('Estado actualizado.', 'exito', 1500); TH.router.refrescar(); },
    'plan-filtro-estado'(el) { ui.planFiltroEstado = el.value; TH.router.refrescar(); },
    'plan-filtro-dim'(el) { ui.planFiltroDim = el.value; TH.router.refrescar(); },
    'biblioteca-cat'(el) { ui.bibliotecaCat = el.value; TH.router.refrescar(); },
    'biblioteca-tema'(el) { ui.bibliotecaTema = el.value; TH.router.refrescar(); }
  });
  function refrescarConFoco(id, el) { const pos = el.selectionStart; TH.router.ir(TH.router.actual().ruta + '?sinScroll=1'); const n = document.getElementById(id); if (n) { n.focus(); try { n.setSelectionRange(pos, pos); } catch (_) { } } }
  Object.assign(TH.entradas, {
    'biblioteca-q'(el) { ui.bibliotecaQ = el.value; refrescarConFoco('bq', el); },
    'plan-filtro-resp'(el) { ui.planFiltroResp = el.value; refrescarConFoco('f-resp', el); }
  });
  Object.assign(TH.formularios, {
    async 'org-perfil'(form) { if (!TH.ui.validar(form)) return; const r = await TH.ui.ejecutar(form, () => TH.api.organizaciones.actualizar(orgId(), TH.ui.datosFormulario(form)), { texto: 'Guardando…', exito: 'Perfil actualizado.' }); if (!r.ok) return; await TH.api.organizaciones.marcarOnboarding(orgId(), 'perfil'); TH.router.refrescar(); },
    async 'diag-responder'(form, ev, silencioso) {
      const opcion = form.elements.opcion.value; const just = form.elements.justificacion ? form.elements.justificacion.value : '';
      if (!opcion) { TH.ui.toast('Selecciona una opción para continuar.', 'error'); form.querySelector('input[type=radio]').focus(); return; }
      TH.ui.ocupado(form, true, 'Guardando…');
      const r = await TH.api.diagnostico.responder(orgId(), form.dataset.pregunta, opcion, just);
      TH.ui.ocupado(form, false);
      if (!r.ok) { const c = document.getElementById('diag-justificacion'); if (c && r.errores && r.errores.justificacion) { c.classList.add('es-invalido'); c.querySelector('.campo__error').textContent = r.errores.justificacion; c.querySelector('textarea').focus(); } else if (c && /justific/i.test(r.error || '')) { c.classList.add('es-invalido'); c.querySelector('.campo__error').textContent = r.error; c.querySelector('textarea').focus(); } else TH.ui.errorApi(r); return; }
      if (silencioso) return;
      const d = TH.api.diagnostico.obtener(orgId()); const idx = d.preguntaActual;
      if (idx < preguntas().length - 1) TH.acciones['diag-ir']({ dataset: { indice: String(idx + 1) } }); else TH.router.ir('/organizacion/diagnostico?revisar=1&sinScroll=1');
    },
    async 'plan-generar'(form) {
      const sel = [...form.querySelectorAll('input[name=sel]:checked')].map(c => c.value);
      const plan = TH.api.plan.obtener(orgId());
      const r = await TH.ui.ejecutar(form, () => plan ? TH.api.plan.incorporarSugeridas(orgId(), sel) : TH.api.plan.crearDesdeDiagnostico(orgId(), sel), { texto: 'Creando plan…' });
      if (!r.ok) return;
      ui.seleccionSug = null; TH.ui.toast(plan ? r.agregadas + ' recomendaciones incorporadas.' : 'Plan creado con ' + r.plan.acciones.length + ' acciones. Asigna responsables y fechas.', 'exito', 5000); TH.router.ir('/organizacion/plan-accion');
    },
    async 'plan-editar'(form) { form.querySelectorAll('.campo').forEach(c => c.classList.remove('es-invalido')); const d = TH.ui.datosFormulario(form); const e = TH.api.plan.validarAccion(d); if (Object.keys(e).length) { TH.ui.mostrarErrores(form, e); return; } const r = await TH.ui.ejecutar(form, () => TH.api.plan.actualizarAccion(orgId(), form.dataset.id, d), { texto: 'Guardando…', exito: 'Acción actualizada.' }); if (r.ok) TH.router.refrescar(); },
    async 'plan-nueva'(form) { form.querySelectorAll('.campo').forEach(c => c.classList.remove('es-invalido')); const r = await TH.ui.ejecutar(form, () => TH.api.plan.agregarAccion(orgId(), TH.ui.datosFormulario(form)), { texto: 'Guardando…', exito: 'Acción añadida al plan.' }); if (!r.ok) return; TH.ui.cerrarModal(); TH.router.ir('/organizacion/plan-accion'); },
    async 'plan-reprogramar'(form) { if (!TH.ui.validar(form)) return; const a = TH.api.plan.obtener(orgId()).acciones.find(x => x.id === form.dataset.id); const r = await TH.ui.ejecutar(form, () => TH.api.plan.actualizarAccion(orgId(), form.dataset.id, { fechaObjetivo: form.elements.fechaObjetivo.value, estado: a && a.avance > 0 ? 'en-ejecucion' : 'pendiente', observaciones: ((a && a.observaciones) ? a.observaciones + '\n' : '') + TH.util.hoy() + ' · Reprogramada: ' + form.elements.observaciones.value.trim() }), { texto: 'Guardando…', exito: 'Acción reprogramada.' }); if (!r.ok) return; TH.ui.cerrarModal(); TH.router.refrescar(); },
    async 'evidencia-nueva'(form) {
      if (!TH.ui.validar(form)) return; const d = TH.ui.datosFormulario(form); const f = form.elements.archivo && form.elements.archivo.files && form.elements.archivo.files[0];
      if (f) { const lim = TH.config.archivos; const campo = form.elements.archivo.closest('.campo'); if (f.size > lim.maxBytes) { campo.classList.add('es-invalido'); campo.querySelector('.campo__error').textContent = 'El archivo supera ' + Math.round(lim.maxBytes / 1048576) + ' MB.'; return; } if (f.type && !lim.tipos.includes(f.type)) { campo.classList.add('es-invalido'); campo.querySelector('.campo__error').textContent = 'Tipo de archivo no permitido.'; return; } }
      const r = await TH.ui.ejecutar(form, () => TH.api.evidencias.registrar(orgId(), { accionId: form.dataset.accion, nombre: d.nombre, tipo: d.tipo, descripcion: d.descripcion, archivo: f ? { nombre: f.name, tamano: f.size, mime: f.type } : null, archivoFile: f || null }), { texto: f ? 'Cargando archivo…' : 'Registrando…', exito: 'Evidencia registrada.' });
      if (!r.ok) return; TH.ui.cerrarModal(); TH.router.refrescar();
    },
    async 'colab-invitar'(form) { if (!TH.ui.validar(form)) return; const d = TH.ui.datosFormulario(form); d.modulos = [].concat(d.modulos || []); const r = await TH.ui.ejecutar(form, () => TH.api.invitaciones.crear(orgId(), d), { texto: 'Creando…' }); if (!r.ok) return; await TH.api.organizaciones.marcarOnboarding(orgId(), 'colaboradores'); TH.ui.cerrarModal(); ui.colabTab = 'invitaciones'; TH.ui.toast('Invitación creada. Código: ' + r.invitacion.codigo, 'exito', 7000); TH.router.refrescar(); },
    async 'colab-asignar'(form) { const d = TH.ui.datosFormulario(form); const r = await TH.ui.ejecutar(form, () => TH.api.invitaciones.asignarModulos(form.dataset.inv, [].concat(d.modulos || [])), { exito: 'Módulos asignados.' }); if (!r.ok) return; TH.ui.cerrarModal(); TH.router.refrescar(); },
    async 'colab-asignar-usuario'(form) { const d = TH.ui.datosFormulario(form); const r = await TH.ui.ejecutar(form, () => TH.api.formacion.asignarModulosUsuario(form.dataset.user, [].concat(d.modulos || [])), { exito: 'Módulos asignados.' }); if (!r.ok) return; TH.ui.cerrarModal(); TH.router.refrescar(); },
    async 'cambiar-clave'(form) { if (!TH.ui.validar(form)) return; if (form.elements.nueva.value !== form.elements.confirmacion.value) { TH.ui.mostrarErrores(form, { confirmacion: 'Las contraseñas no coinciden.' }); return; } const r = await TH.ui.ejecutar(form, () => TH.auth.cambiarClave(form.elements.actual.value, form.elements.nueva.value), { texto: 'Actualizando…', exito: 'Contraseña actualizada.' }); if (r.ok) form.reset(); }
  });

  TH.router.registrarVarias({
    '/organizacion/inicio': { roles: ROLES, titulo: 'Inicio', render: inicio },
    '/organizacion/perfil': { roles: ROLES, titulo: 'Perfil organizacional', render: perfil },
    '/organizacion/diagnostico': { roles: ROLES, titulo: 'Autodiagnóstico', render: diagnostico },
    '/organizacion/diagnostico/resultados': { roles: ROLES, titulo: 'Resultados y brechas', render: resultados },
    '/organizacion/plan-accion': { roles: ROLES, titulo: 'Plan de acción', render: planAccion, ancho: true },
    '/organizacion/plan-accion/seguimiento': { roles: ROLES, titulo: 'Seguimiento de compromisos', render: seguimiento },
    '/organizacion/plan-accion/detalle': { roles: ROLES, titulo: 'Detalle de acción', render: planDetalle },
    '/organizacion/colaboradores': { roles: ROLES, titulo: 'Colaboradores', render: colaboradores },
    '/organizacion/sensibilizacion': { roles: ROLES, titulo: 'Sensibilización', render: sensibilizacion },
    '/organizacion/biblioteca': { roles: ROLES, titulo: 'Biblioteca', render: (ctx) => biblioteca(ctx, 'organizacion') },
    '/organizacion/reportes': { roles: ROLES, titulo: 'Reportes', render: reportes },
    '/organizacion/sello': { roles: ROLES, titulo: 'Sello Turquesa', render: sello },
    '/organizacion/configuracion': { roles: ROLES, titulo: 'Cuenta y datos', render: configuracion }
  });
})();
